<?php
 namespace Pterodactyl\Jobs\Dezerx; use Throwable; use Illuminate\Bus\Queueable; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Redis; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Contracts\Queue\ShouldBeEncrypted; use Illuminate\Foundation\Bus\Dispatchable; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Services\Dezerx\DiscordBot\Style; use Pterodactyl\Services\Dezerx\DiscordBot\Linker; use Pterodactyl\Services\Dezerx\DiscordBot\Deferral; use Pterodactyl\Services\Dezerx\DiscordBot\ClientApi; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\BotSettings; use Pterodactyl\Services\Dezerx\DiscordBot\DiscordRest; use Pterodactyl\Services\Dezerx\DiscordBot\Views\ControlPanel; class RefreshControlPanel implements ShouldQueue, ShouldBeEncrypted { use Dispatchable; use InteractsWithQueue; use Queueable; use SerializesModels; public const INTERVAL = 10; public const WINDOW = 300; public const RETRY = 4; public const MAX_LIVE = 12; private const MAX_BACKOFF = 50; private const LIVE_SET = 'dzb:cp-live-set'; private float $due = 0.0; public int $tries = 1; public int $timeout = 25; public function __construct( private int $botId, private string $discordUserId, private bool $personal, private array $allowed, private string $token, private string $server, private string $nonceKey, private string $nonce, private float $until, ) { $this->onQueue('low'); } public static function arm(DiscordBot $bot, string $channelId, string $userId, bool $personal, array $allowed, string $token, string $server, int $delay = self::INTERVAL): void { $key = self::key($bot->id, $channelId, $userId); if (!self::claim($key)) { Cache::forget($key); return; } $nonce = hash('sha256', $token); Cache::put($key, $nonce, self::WINDOW + 30); self::enqueue(new self($bot->id, $userId, $personal, $allowed, $token, $server, $key, $nonce, microtime(true) + self::WINDOW), $delay); } public function handle(): void { Deferral::fresh(); if (!BotConfig::enabled() || Cache::get($this->nonceKey) !== $this->nonce) { return; } $bot = DiscordBot::query()->find($this->botId); if ($bot === null || !BotConfig::serves($bot) || !BotSettings::enabled($bot, 'controlpanel')) { self::release($this->nonceKey); return; } $api = $this->resolveApi($bot); if ($api === null || !$api->usable()) { self::release($this->nonceKey); return; } Style::use(Style::for($bot), $this->allowed, BotSettings::powerActions($bot)); $paused = microtime(true) >= $this->until; $notice = null; try { $message = ControlPanel::build($api, $this->server, $notice, false, $paused); } catch (Throwable) { self::release($this->nonceKey); return; } $files = $message['_files'] ?? []; $retry = (bool) ($message['_retry'] ?? false); unset($message['_files'], $message['_live'], $message['_retry']); $ok = app(DiscordRest::class)->editOriginal($bot, $this->token, $message, is_array($files) ? $files : []); if (!$ok || $paused) { if ($paused) { Cache::forget($this->nonceKey); } self::release($this->nonceKey); return; } $late = $this->due > 0 ? max(0.0, microtime(true) - $this->due) : 0.0; $delay = ($retry ? self::RETRY : self::INTERVAL) + (int) min(self::MAX_BACKOFF, round($late * 2)); self::enqueue(new self($this->botId, $this->discordUserId, $this->personal, $this->allowed, $this->token, $this->server, $this->nonceKey, $this->nonce, $this->until), $delay); } private function resolveApi(DiscordBot $bot): ?ClientApi { if ($this->personal) { return ClientApi::forBot($bot); } $member = Linker::memberFor($this->discordUserId); return $member !== null && $member->user !== null ? ClientApi::for($member) : null; } private static function key(int $botId, string $channelId, string $userId): string { return 'dzb:cp-live:' . $botId . ':' . $channelId . ':' . $userId; } public static function stop(DiscordBot $bot, string $channelId, string $userId): void { $key = self::key($bot->id, $channelId, $userId); Cache::forget($key); self::release($key); } private static function enqueue(self $job, int $delay): void { $job->due = microtime(true) + $delay; dispatch($job)->delay(now()->addSeconds($delay)); } private static function claim(string $key): bool { try { $redis = Redis::connection(); $now = time(); $redis->zremrangebyscore(self::LIVE_SET, '-inf', (string) $now); if ($redis->zscore(self::LIVE_SET, $key) === null && (int) $redis->zcard(self::LIVE_SET) >= self::MAX_LIVE) { return false; } $redis->zadd(self::LIVE_SET, [$key => $now + self::WINDOW + 60]); return true; } catch (Throwable) { return true; } } private static function release(string $key): void { try { Redis::connection()->zrem(self::LIVE_SET, $key); } catch (Throwable) { } } } 